<?php
require_once 'koneksi.php';function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$tanggal=$_GET['tanggal']??date('Y-m-d');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$tanggal))$tanggal=date('Y-m-d');
$stmt=$conn->prepare("SELECT COUNT(*) jumlah_pesanan,COALESCE(SUM(total),0) omzet FROM pesanan WHERE DATE(created_at)=?");$stmt->bind_param('s',$tanggal);$stmt->execute();$ringkas=$stmt->get_result()->fetch_assoc();$stmt->close();
$stmt=$conn->prepare("SELECT m.nama,SUM(pd.qty) terjual,SUM(pd.subtotal) omzet FROM pesanan_detail pd JOIN pesanan p ON p.id=pd.pesanan_id JOIN menu m ON m.id=pd.menu_id WHERE DATE(p.created_at)=? GROUP BY m.id,m.nama ORDER BY terjual DESC,omzet DESC");$stmt->bind_param('s',$tanggal);$stmt->execute();$terlaris=$stmt->get_result();
$stmt=$conn->prepare("SELECT nomor_antrian,total,status,metode_bayar,created_at FROM pesanan WHERE DATE(created_at)=? ORDER BY created_at DESC");$stmt->bind_param('s',$tanggal);$stmt->execute();$orders=$stmt->get_result();
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Laporan Penjualan</title><link rel="stylesheet" href="style.css"></head><body><header class="topbar"><div class="topbar-inner"><a class="brand" href="index.php"><span class="brand-mark">K</span><span>Kantin<span class="brand-light">Sekolah</span></span></a><nav class="nav"><a href="index.php">Kasir</a><a href="display.php">Display Antrean</a><a href="dapur.php">Dapur</a><a href="admin.php">Kelola Menu</a><a class="active" href="laporan.php">Laporan</a></nav></div></header>
<main class="page"><section class="page-heading"><div><p class="eyebrow">REKAP TRANSAKSI</p><h1>Laporan Penjualan</h1><p class="muted">Rekap penjualan harian dan menu terlaris.</p></div><button class="button button-secondary" onclick="window.print()">Cetak Laporan</button></section><form method="get" class="panel" style="padding:18px;display:flex;gap:12px;align-items:end;flex-wrap:wrap"><label>Tanggal laporan<input type="date" name="tanggal" value="<?= e($tanggal) ?>"></label><button class="button button-primary">Tampilkan</button></form>
<section class="stats-grid"><div class="stat-card"><div><small>Jumlah pesanan</small><strong><?= (int)$ringkas['jumlah_pesanan'] ?></strong></div></div><div class="stat-card"><div><small>Total penjualan</small><strong>Rp <?= number_format((int)$ringkas['omzet'],0,',','.') ?></strong></div></div></section>
<section class="panel" style="padding:20px;margin-top:20px"><h2>Menu Terlaris</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Menu</th><th>Jumlah Terjual</th><th>Omzet</th></tr></thead><tbody><?php if(!$terlaris->num_rows): ?><tr><td colspan="3">Belum ada penjualan.</td></tr><?php else:while($r=$terlaris->fetch_assoc()): ?><tr><td><?= e($r['nama']) ?></td><td><?= (int)$r['terjual'] ?></td><td>Rp <?= number_format((int)$r['omzet'],0,',','.') ?></td></tr><?php endwhile;endif; ?></tbody></table></div></section>
<section class="panel" style="padding:20px;margin-top:20px"><h2>Transaksi Harian</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Antrean</th><th>Waktu</th><th>Status</th><th>Pembayaran</th><th>Total</th></tr></thead><tbody><?php if(!$orders->num_rows): ?><tr><td colspan="5">Belum ada transaksi.</td></tr><?php else:while($r=$orders->fetch_assoc()): ?><tr><td>#<?= (int)$r['nomor_antrian'] ?></td><td><?= e(date('H:i',strtotime($r['created_at']))) ?></td><td><?= e(ucfirst($r['status'])) ?></td><td><?= e(strtoupper($r['metode_bayar']??'tunai')) ?></td><td>Rp <?= number_format((int)$r['total'],0,',','.') ?></td></tr><?php endwhile;endif; ?></tbody></table></div></section></main></body></html>